    node, python, publicOrigin: publicUrl.origin, hostname: publicUrl.hostname, sellerPort, operationsPort,
    receiverPort: checkout ? receiverPort : null, outbox, receiverState, delivery: delivery ?? null,
    ...(retained ? { release: retained.release, discovery: retained.discovery, discoveryPort } : {}),
    target: prefix + '.target', services, routes, inputFiles, sourceEntries, planFile };
}

const DOC_PATHS = ['/_seller/offers','/_seller/docs','/_seller/docs/','/_seller/openapi.json',
  '/_seller/developer/browser.mjs','/_seller/developer/request.mjs','/_seller/developer/style.css',
  '/_seller/client/seller-client.mjs','/_seller/client/seller-client.d.mts','/_seller/client/README.md','/_seller/client/package.json'];
export function caddyfile(p) {
  const blocks = p.routes.map((r, i) => `  @route${i} {\n    method ${r.method}\n    path_regexp route${i} ${caddyToken(r.pattern)}\n  }\n  handle @route${i} {\n    reverse_proxy 127.0.0.1:${p.sellerPort} {\n      transport http {\n        keepalive off\n      }\n    }\n  }`);
  blocks.push(`  @documentation {\n    method GET HEAD\n    path ${DOC_PATHS.join(' ')}\n  }\n  handle @documentation {\n    reverse_proxy 127.0.0.1:${p.sellerPort} {\n      transport http {\n        keepalive off\n      }\n    }\n  }`);
  if (p.discovery) {
    blocks.push(`  @discovery {\n    method GET\n    path ${p.discovery.paths.join(' ')}\n  }\n  handle @discovery {\n    reverse_proxy 127.0.0.1:${p.discoveryPort} {\n      header_up Host 127.0.0.1:${p.discoveryPort}\n      header_up -Origin\n      header_up -Sec-Fetch-Site\n      header_up -Authorization\n      header_up -Cookie\n      transport http {\n        keepalive off\n      }\n    }\n  }`);
    if (p.discovery.sourceMatchPath !== '/_seller/offers') blocks.push(
      `  @offerExport {\n    method GET\n    path_regexp offerExport ${caddyToken('^' + regex(p.discovery.sourceMatchPath) + '$')}\n  }\n  handle @offerExport {\n    rewrite * /_seller/offers\n    reverse_proxy 127.0.0.1:${p.sellerPort} {\n      transport http {\n        keepalive off\n      }\n    }\n  }`);
  }
  if (p.receiverState) blocks.push(
    `  @settledEvent {\n    method POST\n    path /internal/x402-events\n  }\n  handle @settledEvent {\n    rewrite * /sf98/events\n    reverse_proxy 127.0.0.1:${p.receiverPort} {\n      transport http {\n        keepalive off\n      }\n    }\n  }`,
    `  @approvedFile {\n    method GET\n    path_regexp approvedFile ^/deliver/[A-Za-z0-9._:-]{1,80}$\n  }\n  handle @approvedFile {\n    reverse_proxy 127.0.0.1:${p.receiverPort} {\n      transport http {\n        keepalive off\n      }\n    }\n  }`);
  return `# Import this site's fragment into the existing Caddyfile.\n# Query, payment, order and bearer headers pass unchanged. No automatic retries or access log.\n${p.publicOrigin} {\n${blocks.join('\n')}\n  handle {\n    respond "Not found" 404\n  }\n}\n`;
}

export function serviceUnit(p, s, bundle) {
  // Start receiver -> sender -> seller; stop seller -> sender -> receiver.
  const predecessor = s.role === 'seller' && p.discovery ? p.services.find(x => x.role === 'discovery')?.unit :
    s.role === 'seller' && p.delivery ? p.services.find(x => x.role === 'delivery')?.unit :
    s.role === 'delivery' && p.receiverState ? p.services.find(x => x.role === 'receiver')?.unit : null;
  const check = [p.node, join(p.sourceRoot, BASE + 'sf99-merchant-deploy/cli.mjs'), 'check', '--bundle', bundle];
  const oauthStores = s.role === 'seller' ? (p.oauthConnections ?? []) : [];
  const writable = [p.stateRoot, ...oauthStores.map(entry => entry.directory)];
  const oauthPreflight = oauthStores.length ? 'ExecStartPre=' + commandLine([
    p.node, join(p.sourceRoot, BASE + 'sf30-seller-sdk/oauth-connections/host-check.mjs'),
    '--bundle', bundle]) + '\n' : '';
  return `[Unit]\nDescription=Stellar Forge ${p.merchant} ${s.role}\nWants=network-online.target\nAfter=network-online.target${predecessor ? ' ' + predecessor : ''}\nPartOf=${p.target}\n\n[Service]\nType=exec\nUser=${p.serviceUser}\nGroup=${p.serviceGroup}\nWorkingDirectory=${(/\s$/.test(p.sourceRoot) ? p.sourceRoot + '/.' : p.sourceRoot).replaceAll('%', '%%')}\nUMask=0077\n${p.environmentFile ? 'EnvironmentFile=' + p.environmentFile.replaceAll('%', '%%') + '\n' : ''}Environment=PYTHONDONTWRITEBYTECODE=1\nExecStartPre=${commandLine(check)}\n${oauthPreflight}${s.initialize ? 'ExecStartPre=' + commandLine(s.initialize) + '\n' : ''}ExecStart=${commandLine(s.args)}\nRestart=on-failure\nRestartSec=5\n${s.role === 'delivery' ? 'RestartPreventExitStatus=75\n' : ''}KillMode=mixed\nTimeoutStopSec=${s.stopSeconds}\nNoNewPrivileges=true\nPrivateTmp=true\nProtectSystem=strict\nProtectHome=read-only\nReadWritePaths=${writable.map(value => unitWord(value)).join(' ')}\n\n[Install]\nWantedBy=${p.target}\n`;
}
export function recoveryPlan(p) {
  const roots = [{ name: 'merchantState', path: p.stateRoot }];
  for (const [i, input] of p.inputFiles.entries()) if (!inside(p.stateRoot, input.path)) roots.push({ name: 'configuration' + i, path: input.path });
  return { schema: 'stellar-forge.merchant-recovery-plan.v1', roots };
}
export async function generate(planFile, output, options) {
  const p = await prepare(planFile, options), out = path(resolve(output), 'output');
  need(!inside(p.sourceRoot, out) && !inside(p.stateRoot, out) && !inside(out, p.stateRoot) &&
    !p.inputFiles.some(f => inside(out, f.path)) &&
    !(p.oauthConnections ?? []).some(entry => inside(out, entry.directory) || inside(entry.directory, out)),
    'Deployment bundle must be separate from code, inputs, merchant state and private OAuth stores');
  const artifacts = new Map([['Caddyfile', caddyfile(p)], [p.target,
    `[Unit]\nDescription=Stellar Forge ${p.merchant} merchant services\nWants=${p.services.map(s => s.unit).join(' ')}\nAfter=network-online.target\n\n[Install]\nWantedBy=multi-user.target\n`],
    ['recovery-plan.json', JSON.stringify(recoveryPlan(p), null, 2) + '\n']]);
  for (const s of p.services) artifacts.set(s.unit, serviceUnit(p, s, out));
  const { renderRunbook } = await import('./runbook.mjs');
  artifacts.set('RUNBOOK.md', renderRunbook(p, out));
  const manifest = { ...p, bundle: out, artifacts: Object.fromEntries([...artifacts].map(([name, value]) => [name, hash(value)])) };
  let created = false;
  try {
    await mkdir(out, { mode: 0o700 }); created = true;
    for (const [name, value] of artifacts) await writeFile(join(out, name), value, { flag: 'wx', mode: 0o600 });
    await writeFile(join(out, 'deployment.json'), JSON.stringify(manifest, null, 2) + '\n', { flag: 'wx', mode: 0o600 });
    return { bundle: out, merchant: p.merchant, kind: p.kind, mode: p.mode, publicOrigin: p.publicOrigin,
      target: p.target, services: p.services.map(s => s.unit), routes: p.routes.length, files: artifacts.size + 1 };
  } catch (error) { if (created) await rm(out, { recursive: true, force: true }); throw error; }
}

export async function checkBundle(bundle) {
  bundle = path(resolve(bundle), 'bundle');
  const p = await json(join(bundle, 'deployment.json'));
  need(p.schema === SCHEMA && p.bundle === bundle && object(p.artifacts) &&
    Array.isArray(p.inputFiles) && Array.isArray(p.sourceEntries), 'Original deployment manifest required at its generated path');
  for (const [name, expected] of Object.entries(p.artifacts)) {
    need(/^[A-Za-z0-9_.-]+$/.test(name) && /^[a-f0-9]{64}$/.test(expected), 'Invalid deployment artifact');
    need(hash(await bytes(join(bundle, name), 4 * 1024 * 1024)) === expected, 'Deployment artifact changed: ' + name);
  }
  for (const item of [...p.inputFiles, ...p.sourceEntries]) {
    path(item.path, 'retained input');
    need(hash(await bytes(item.path, 8 * 1024 * 1024)) === item.sha256, 'Source/configuration changed; regenerate the host bundle: ' + item.path);
  }
  if (p.environmentFile) {
    const env = await lstat(p.environmentFile);
    need(env.isFile() && !env.isSymbolicLink() && (env.mode & 0o077) === 0,
      'Use a private regular environmentFile with no group or world access');
  }
  validateOAuthHostDirectories(p, { bundle });
  if (p.kind === 'release') await checkRetainedRelease(p);
  return p;
}

// MIT. Bind the original SF82 selection and discovery identity to an SF99 host.
import { lstat, realpath } from 'node:fs/promises';
import { isAbsolute, join, resolve } from 'node:path';
import { readReleaseState, inspectRelease, releaseStatus } from '../sf82-seller-pilot/releases.mjs';
import { inspectReleaseDiscoverySetup } from '../sf82-seller-pilot/release-discovery-setup.mjs';

export const DISCOVERY_PATHS = Object.freeze(['/discovery/resources', '/discovery/search']);
const need = (value, message) => { if (!value) throw new Error(message); };
const inside = (root, file) => file === root || file.startsWith(root + '/');
const object = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const fields = (value, names, label) => need(object(value) && Object.keys(value).every(key => names.includes(key)),
  'Unknown or invalid ' + label + ' field');

async function directory(value, stateRoot, label) {
  need(typeof value === 'string' && isAbsolute(value) && resolve(value) === value &&
    !/[\\\x00-\x1f\x7f]/.test(value) && inside(stateRoot, value) && value !== stateRoot,
    label + ' must be a separate descendant of privateRoot');
  const meta = await lstat(value);
  need(meta.isDirectory() && !meta.isSymbolicLink() && await realpath(value) === value && !(meta.mode & 0o077),
    'Use the original private real ' + label + ' directory');
  return meta;
}

/** Read original immutable source; this never imports applications or starts a writer. */
export async function prepareRetainedRelease(raw, { stateRoot, sourceRoot }) {
  fields(raw.release, ['store', 'expectedGeneration'], 'retained release');
  const { store, expectedGeneration } = raw.release;
  await directory(store, stateRoot, 'release store');
  need(Number.isSafeInteger(expectedGeneration) && expectedGeneration >= 0,
    'release.expectedGeneration must be the current original release status generation');
  const state = await readReleaseState(store);
  need(state.active && state.generation === expectedGeneration,
    'The active release selection changed; inspect original release status and regenerate the host plan');
  const release = await inspectRelease(store, state.active);
  need((release.runtime.facilitator ? 'native' : 'challenge') === raw.mode,
    'Host mode must match the immutable release runtime');
  need(Number.isInteger(release.runtime.port) && release.runtime.port >= 1024 && release.runtime.port <= 65535,
    'Stage the original release with its actual fixed host port (1024–65535), then activate it');
  need(!release.runtime.allowLocalFacilitator, 'Production retained releases use their original HTTPS facilitator');
  const sourceFiles = [];
  if (release.handlerEntry) {
    need(inside(sourceRoot, release.handlerEntry.path),
      'Retained trusted handlers must belong to the selected immutable source release; stage its host path before deployment');
    sourceFiles.push(release.handlerEntry.path);
  }
  // These native journals name an absolute writable directory inside the frozen
  // binding. The existing API host owns their path-rebasing recovery. Do not
  // silently move an immutable release while leaving it writing previous state.
  need(!release.routes.some(route => route.upstream?.idempotency),
    'Absolute upstream idempotency journals use the original kind:api host and its restored-path workflow');
  const oauthRequirements = [...new Map(release.routes.filter(route => route.upstream?.oauthConnection)
    .map(route => [route.upstream.binding, { binding: route.upstream.binding,
      origin: route.upstream.origin, connection: route.upstream.oauthConnection }])).values()];
  const releaseDirectory = join(store, 'releases', release.id);
  const inputPaths = [join(store, 'state.json'), join(releaseDirectory, 'release.json'),
    join(releaseDirectory, 'manifest.json'), join(releaseDirectory, 'offers.json')];
  let discovery = null;
  if (raw.discovery !== undefined) {
    fields(raw.discovery, ['setup'], 'discovery');
    const meta = await directory(raw.discovery.setup, stateRoot, 'discovery setup');
    need(!inside(store, raw.discovery.setup) && !inside(raw.discovery.setup, store),
      'Keep the original discovery setup separate from the release store');
    // Root maintenance inspects the same service-owned files. Actual catalog-run
    // still requires the launching account to own every original private file.
    const setup = await inspectReleaseDiscoverySetup(store, { directory: raw.discovery.setup, ownerUid: meta.uid });
    need(setup.source.publicOrigin === release.publicOrigin,
      'Retained merchant and existing discovery setup must use the same public origin');
    const source = new URL(setup.source.sourceURL);
    let sourceMatchPath;
    try { sourceMatchPath = decodeURIComponent(source.pathname); }
    catch { throw new Error('Discovery offer export has an invalid escaped path'); }
    need(!source.search && !source.hash && !DISCOVERY_PATHS.includes(sourceMatchPath) &&
      !/[\\\x00-\x1f\x7f]/.test(sourceMatchPath),
      'The generated public offer export requires its own exact path without a query or fragment');
    discovery = { directory: setup.directory, catalogDirectory: setup.catalogDirectory,
      connectionFile: setup.connectionFile, policyFile: setup.policyFile,
      enrollmentFile: setup.enrollmentFile, sellerId: setup.sellerId,
      publicKeySha256: setup.publicKeySha256, policySha256: setup.policySha256,
      sourceReleaseId: setup.source.releaseId, sourceURL: setup.source.sourceURL,
      sourcePath: source.pathname, sourceMatchPath, paths: [...DISCOVERY_PATHS] };
    inputPaths.push(...['setup.json', 'connection.json', 'policy.json', 'seller-public.pem', 'seller-enrollment.json']
      .map(file => join(setup.directory, file)));
  }
  const after = await readReleaseState(store);
  need(after.active === release.id && after.generation === expectedGeneration,
    'The release selection changed while preparing this host; refresh original status');
  return { configPath: join(releaseDirectory, 'seller-service.json'), port: release.runtime.port,
    facilitator: release.runtime.facilitator ?? null, inputPaths, sourceFiles, discovery,
    oauthRequirements, allowLoopbackUpstream: release.runtime.allowLoopbackUpstream === true,
    release: { store, id: release.id, digest: release.digest, expectedGeneration,
      source: release.source, publicOrigin: release.publicOrigin } };
}

/** Every service preflight reuses the source owner's complete verifier. */
export async function checkRetainedRelease(p) {
  const prepared = await prepareRetainedRelease({ mode: p.mode,
    release: { store: p.release.store, expectedGeneration: p.release.expectedGeneration },
    ...(p.discovery ? { discovery: { setup: p.discovery.directory } } : {}) }, p);
  need(JSON.stringify(prepared.release) === JSON.stringify(p.release) &&
    JSON.stringify(prepared.discovery) === JSON.stringify(p.discovery),
    'Retained release or discovery identity changed; regenerate the host bundle');
  need(prepared.port === p.sellerPort, 'Retained listener port changed');
  const order = rows => [...rows].sort((a, b) => a.binding.localeCompare(b.binding));
  need(JSON.stringify(order(prepared.oauthRequirements)) ===
    JSON.stringify(order((p.oauthConnections ?? []).flatMap(entry => entry.bindings))),
    'Retained OAuth grant selection changed; regenerate the original host bundle');
  return prepared;
}

export async function retainedRuntimeCheck(p) {
  const status = await releaseStatus(p.release.store), observed = status.runtime.observed;
  return { name: 'original retained process and source', expected: p.release.id,
    actual: observed?.releaseId ?? null, state: status.runtime.state,
    passed: status.runtime.state === 'RUNNING' && observed?.releaseId === p.release.id &&
      observed.releaseDigest === p.release.digest && observed.listener === `http://127.0.0.1:${p.sellerPort}` };
}

/** Rebase only host selections, retaining original release, key and journal bytes. */
export function restoreRetainedSelections(raw, previous, mapped) {
  const result = structuredClone(raw);
  result.release.store = mapped(previous.release.store, 'release.store');
  if (previous.discovery) result.discovery.setup = mapped(previous.discovery.directory, 'discovery.setup');
  return result;
}
